def count_vowels(text):
    vowels = "aeiouy"
    count = 0
    for letter in text:
        if letter in vowels:
            count = count + 1
    return count

def grade_text(grade):
    if grade == 5:
        return "świetnie"
    elif grade == 4:
        return "dobrze"
    else:
        return "może być"

def who_wins(a, b):
    if a == b:
        return "remis"
    if a == "kamień" and b == "nożyce":
        return "pierwszy"
    if a == "nożyce" and b == "papier":
        return "pierwszy"
    if a == "papier" and b == "kamień":
        return "pierwszy"
    return "drugi"

def basket_total(prices):
    total = 0
    for name, price in prices.items():
        total += price
    return total

def warm_days(temperatures, limit):
    count = 0
    for temperature in temperatures:
        if temperature >= limit:
            count += 1
    return count

def game_summary(results):
    summary = {"wygrana": 0, "remis": 0, "przegrana": 0}
    for result in results:
        summary[result] += 1
    return summary
